import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.CWWEQfK7.js";const i=JSON.parse('{"title":"命令速查","description":"集中查找 Ershu 六个仓库和本站的安装、运行、检查与构建命令。","frontmatter":{"page_id":"reference-commands","title":"命令速查","description":"集中查找 Ershu 六个仓库和本站的安装、运行、检查与构建命令。"},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md","lastUpdated":1786289447000}'),c={name:"reference/commands.md"};function a(u,t,n,h,s,l){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="命令速查" tabindex="-1">命令速查 <a class="header-anchor" href="#命令速查" aria-label="Permalink to &quot;命令速查&quot;">​</a></h1><p>所有命令都从对应仓库根目录运行。先检查当前分支和工作区，不要把一个仓库的命令复制到另一个仓库执行。</p><h2 id="完整本地环境" tabindex="-1">完整本地环境 <a class="header-anchor" href="#完整本地环境" aria-label="Permalink to &quot;完整本地环境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>命令</th><th>成功判据</th></tr></thead><tbody><tr><td>安装锁定后端组合</td><td><code>uv sync --all-extras --frozen</code></td><td>安装完成且锁文件没有被改写</td></tr><tr><td>启动基础设施</td><td><code>docker compose --env-file .env.compose up -d</code></td><td>Compose 中的服务启动，健康检查最终通过</td></tr><tr><td>查看数据库 head</td><td><code>uv run ershu-db heads</code></td><td>输出当前可发现的升级 head</td></tr><tr><td>升级数据库</td><td><code>uv run ershu-db upgrade head</code></td><td>命令正常结束，数据库到达当前 head</td></tr><tr><td>启动 API</td><td><code>uv run ershu-api</code></td><td><code>http://127.0.0.1:8000/health</code> 返回 <code>ok</code></td></tr><tr><td>启动 MCP</td><td><code>uv run ershu-mcp</code></td><td><code>http://127.0.0.1:8001/health</code> 返回 <code>ok</code></td></tr><tr><td>启动 Worker</td><td><code>uv run ershu-worker</code></td><td>进程持续运行，并能领取已排队任务</td></tr><tr><td>启动定时轮询</td><td><code>uv run ershu-api-poller</code></td><td>进程持续运行并按 UTC 计划检查仓库</td></tr><tr><td>手动轮询一次</td><td><code>uv run ershu-api-poller --once</code></td><td>完成一轮检查后退出，并报告可处理的结果</td></tr></tbody></table><p>完整准备顺序和限制见<a href="/development/local-setup">搭建本地开发环境</a>。</p><h2 id="后端模块检查" tabindex="-1">后端模块检查 <a class="header-anchor" href="#后端模块检查" aria-label="Permalink to &quot;后端模块检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>仓库</th><th>测试</th><th>代码与格式</th><th>构建</th></tr></thead><tbody><tr><td>Core</td><td><code>uv run pytest -m &quot;not integration&quot;</code></td><td><code>uv run ruff check src tests</code><br><code>uv run ruff format --check src tests</code></td><td><code>uv build --wheel</code></td></tr><tr><td>API</td><td><code>uv run --extra dev pytest -q</code></td><td><code>uv run --extra dev ruff check src tests</code><br><code>uv run --extra dev ruff format --check src tests</code></td><td><code>uv build --wheel</code></td></tr><tr><td>Worker</td><td><code>uv run pytest -q</code></td><td><code>uv run ruff check src tests scripts</code><br><code>uv run ruff format --check src tests scripts</code></td><td><code>uv build --wheel</code></td></tr><tr><td>MCP</td><td><code>uv run pytest -q</code></td><td><code>uv run ruff check src tests</code><br><code>uv run ruff format --check src tests</code></td><td><code>uv build --wheel</code></td></tr><tr><td>组合仓库</td><td><code>uv run pytest tests -q</code></td><td><code>uv run ruff check tests scripts</code><br><code>uv run ruff format --check tests scripts</code><br><code>uv run basedpyright --project pyrightconfig.json</code></td><td><code>uv run ershu-db heads</code></td></tr></tbody></table><p>需要外部服务的测试不能用常规单元测试结果代替。具体选择见<a href="/development/quality">质量、提交与 Pull Request</a>。</p><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>命令</th><th>成功判据</th></tr></thead><tbody><tr><td>按锁文件安装</td><td><code>npm ci</code></td><td>安装完成且 <code>package-lock.json</code> 未改写</td></tr><tr><td>启动开发服务器</td><td><code>npm run dev</code></td><td><code>http://localhost:3000</code> 可以打开</td></tr><tr><td>运行测试</td><td><code>npm test</code></td><td>Node.js 测试全部通过</td></tr><tr><td>检查代码与类型</td><td><code>npm run lint</code></td><td>ESLint 与 TypeScript 检查通过</td></tr><tr><td>检查格式</td><td><code>npm run format:check</code></td><td>Prettier 没有报告待格式化文件</td></tr><tr><td>生产构建</td><td><code>npm run build</code></td><td>生成 <code>dist/</code>，命令正常结束</td></tr><tr><td>预览产物</td><td><code>npm run preview</code></td><td>终端显示本地预览地址，页面可以打开</td></tr></tbody></table><h2 id="本站" tabindex="-1">本站 <a class="header-anchor" href="#本站" aria-label="Permalink to &quot;本站&quot;">​</a></h2><p>以下命令在本仓库根目录运行：</p><table tabindex="0"><thead><tr><th>目的</th><th>命令</th><th>成功判据</th></tr></thead><tbody><tr><td>安装</td><td><code>npm ci</code></td><td>依赖按锁文件安装</td></tr><tr><td>本地编写</td><td><code>npm run dev</code></td><td>终端显示本地地址，中英文页面可访问</td></tr><tr><td>内容检查</td><td><code>npm run check:content</code></td><td>双语配对、链接、排版和占位检查通过</td></tr><tr><td>完整检查</td><td><code>npm run check</code></td><td>内容、格式和生产构建全部通过</td></tr><tr><td>预览产物</td><td><code>npm run preview</code></td><td>生产产物可以在本地打开</td></tr></tbody></table><blockquote><p>命令来源：当前安装清单、README 与持续集成配置。某条命令是否已在本站建设过程中执行，请以项目交付报告为准。</p></blockquote>',14)])])}const m=d(c,[["render",a]]);export{i as __pageData,m as default};
